        for (int right = 0; right < s.length(); right++) {
            // Remove the charters until the duplicates are found
            while (charSet.count(s[right])) {
                // We will move left pointer until the duplicate is Remove which
                // is belongs to right pointer
                charSet.erase(s[left]);
                left++;
            }

            // Now the add the right poinetr
            charSet.insert(s[right]);

            // update the MaxLength  j - i + 1
            MaxLength = max(MaxLength, right - left + 1);
        }
        return MaxLength;
    }
